## 3. `script.js`
```js
// ===== Data & DOM references =====
const LANGS = [
  { code: 'es', name: 'Spanish' },
  { code: 'fr', name: 'French' },
  { code: 'de', name: 'German' },
  { code: 'hi', name: 'Hindi' },
];

const els = {
  english: document.getElementById('english'),
  attempt: document.getElementById('attempt'),
  language: document.getElementById('language'),
  checkBtn: document.getElementById('checkBtn'),
  output: document.getElementById('output'),
  modeBadge: document.getElementById('modeBadge'),
};

LANGS.forEach(l => {
  const opt = document.createElement('option');
  opt.value = l.code; opt.textContent = `${l.name} (${l.code})`;
  els.language.appendChild(opt);
});

// ===== Config =====
const USE_MOCK = true; // later set false after backend
els.modeBadge.textContent = USE_MOCK ? 'Mock Mode' : 'Live Mode';

// ===== Helpers =====
const esc = s => s.replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
function wordDiff(expected, attempt){
  const a = expected.trim().split(/\s+/);
  const b = attempt.trim().split(/\s+/);
  const max = Math.max(a.length, b.length);
  const rows = [];
  for(let i=0;i<max;i++){
    const wA = a[i]||''; const wB = b[i]||'';
    rows.push(`<span class="${wA===wB?'hit':'miss'}">${esc(wB||'∅')}</span>`);
  }
  return rows.join(' ');
}

// ===== Main logic =====
async function check(){
  const english = els.english.value.trim();
  const attempt = els.attempt.value.trim();
  const lang = els.language.value;
  if(!english || !attempt){
    alert('Type both the English sentence and your translation.');
    return;
  }
  els.checkBtn.disabled = true;
  els.checkBtn.textContent = 'Checking…';
  try{
    let result;
    if(USE_MOCK){
      // Mock check
      const ref = english
        .replace(/I am/g,'Yo estoy')
        .replace(/I/g,'Yo')
        .replace(/tomorrow/g, lang==='es'?'mañana':'demain');
      const score = Math.max(0, 100 - Math.abs(ref.length - attempt.length)*3);
      result = { is_correct: score>=90, score, reference_translation: ref,
        improved_translation: ref, feedback: 'Mock feedback: length/keyword based.', mistakes: [] };
    } else {
      // Real API (via backend)
      const res = await fetch('/api/check', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ english, attempt, lang })
      });
      if(!res.ok) throw new Error('Server error');
      result = await res.json();
    }

    els.output.classList.add('show');
    els.output.innerHTML = `
      <div class="grid">
        <div class="score">Score: ${Math.round(result.score)}/100 ${result.is_correct ? '✅' : '❌'}</div>
        <div><div class="badge">Reference</div><div>${esc(result.reference_translation)}</div></div>
        <div><div class="badge">Your attempt (diff)</div><div class="diff">${wordDiff(result.improved_translation, attempt)}</div></div>
        <div><div class="badge">Feedback</div><div>${esc(result.feedback)}</div></div>
      </div>`;
  } catch(err){
    console.error(err);
    alert('Something went wrong. Check the console.');
  } finally {
    els.checkBtn.disabled = false;
    els.checkBtn.textContent = 'Check';
  }
}

els.checkBtn.addEventListener('click', check);
```

