## `script.js`  
👉 The **super-simple JS** logic:

```js
// Get elements
const englishEl = document.getElementById('english');
const langEl = document.getElementById('language');
const attemptEl = document.getElementById('attempt');
const outputEl = document.getElementById('output');
const checkBtn = document.getElementById('checkBtn');

// Mock translations (tiny dictionary just for demo)
const mockTranslations = {
  es: { "I am happy": "Estoy feliz" },
  fr: { "I am happy": "Je suis heureux" },
  de: { "I am happy": "Ich bin glücklich" },
  hi: { "I am happy": "मैं खुश हूँ" }
};

// When button clicked
checkBtn.addEventListener('click', () => {
  const english = englishEl.value.trim();
  const attempt = attemptEl.value.trim();
  const lang = langEl.value;

  if(!english || !attempt){
    outputEl.textContent = "Please fill both boxes.";
    return;
  }

  // Find reference translation (if we have it)
  const reference = mockTranslations[lang]?.[english] || "(no mock translation found)";

  // Simple check: is user’s attempt exactly the same?
  let result;
  if(attempt === reference){
    result = "✅ Correct!";
  } else {
    result = `❌ Not quite. Correct: ${reference}`;
  }

  // Show result
  outputEl.textContent = result;
});
```

