## 4. `server.mjs`
👉 this is the **backend** that protects your API key

```js
// server.mjs
import express from "express";
import OpenAI from "openai";
import cors from "cors";

const app = express();
app.use(cors());
app.use(express.json());
app.use(express.static(".")); // serve index.html + js + css

const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY
});

app.post("/api/check", async (req, res) => {
  try {
    const { english, attempt, lang } = req.body;

    const prompt = `
You are a strict language teacher.
- Translate the English sentence into ${lang}.
- Compare student's attempt with your reference.
- Score from 0 to 100.
- Give short feedback.
Return JSON only with: is_correct, score, reference_translation, feedback.
English: ${english}
Student attempt (${lang}): ${attempt}
    `;

    const response = await openai.responses.create({
      model: "gpt-4o-mini",
      input: prompt,
      response_format: {
        type: "json_schema",
        json_schema: {
          name: "Grade",
          schema: {
            type: "object",
            properties: {
              is_correct: { type: "boolean" },
              score: { type: "number" },
              reference_translation: { type: "string" },
              feedback: { type: "string" }
            },
            required: ["is_correct", "score", "reference_translation", "feedback"]
          },
          strict: true
        }
      }
    });

    // Parse structured JSON output
    const result = JSON.parse(response.output[0].content[0].text);
    res.json(result);

  } catch (err) {
    console.error(err);
    res.status(500).json({ error: "OpenAI error" });
  }
});

const port = 3000;
app.listen(port, () => console.log(`Server running at http://localhost:${port}`));
```

